const assert=require('node:assert/strict'),fs=require('node:fs');
const {chromium}=require('C:/Users/kensu/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{const browser=await chromium.launch({channel:'msedge',headless:true});try{
 const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[],downloads=[];
 page.on('pageerror',e=>errors.push(e.message));page.on('download',d=>downloads.push(d));
 const base='http://192.168.1.5:55441';
 const get=async(path,params)=>{const r=await page.request.get(base+path+'?'+new URLSearchParams(params));assert.equal(r.status(),200);return r.json()};
 const options=await get('/api/options',{vintageNotation:'canonical'});assert.equal(options.total,7732);assert(options.vintages.includes('2021'));assert(options.vintages.includes('NV'));assert(!options.vintages.some(v=>/^[(\[]\d{4}[)\]]$/.test(v)));assert(!options.vintages.includes('N.V.'));
 const plain=await get('/api/search',{text:'ピエールの白',vintage:'2021'});
 const phrase='ピエールの白でファインズ取り扱い';
 const result=await get('/api/search',{text:phrase,vintage:'2021'});
 assert(result.rows.length>0);assert(result.conditions.includes('取扱先 ファインズ'));
 assert.deepEqual(result.rows.map(r=>r.supplierProductId).sort(),plain.rows.filter(r=>r.supplierName==='ファインズ').map(r=>r.supplierProductId).sort());
 const wrapped=await get('/api/search',{text:phrase,vintage:'[2021]'});assert.deepEqual(wrapped.rows.map(r=>r.supplierProductId),result.rows.map(r=>r.supplierProductId));
 const nv=await get('/api/search',{vintage:'N.V.'});assert(nv.rows.length>0);assert(nv.rows.every(r=>r.vintageLabel==='NV'));
 await page.goto(base);await page.waitForFunction(()=>document.querySelectorAll('#rows tr').length>0&&!document.querySelector('#search').inert);
 const search=async(text,vintage)=>{await page.locator('#text').fill(text);await page.selectOption('#vintage',vintage);const response=page.waitForResponse(r=>r.url().includes('/api/search?'));await page.locator('button[type=submit]').click();await response;await page.waitForFunction(()=>document.querySelector('#busy').hidden&&!document.querySelector('#search').inert)};
 await search(phrase,'2021');assert.equal(await page.locator('#rows tr').count(),result.rows.length);
 const selected=await page.locator('#rows tr').first().innerText();await page.locator('.product-select').first().check();
 await search('イタリアの赤ワインで2500円から4000円','');assert(await page.locator('.product-select').count()>0);await page.locator('.product-select').first().check();
 await page.locator('#download-csv').click();assert.equal(downloads.length,0);assert.equal(await page.locator('#selected-rows tr').count(),2);
 const firstSku=result.rows.find(r=>selected.includes('SKU '+r.sku)).sku;
 await page.locator('#selected-rows tr').filter({hasText:'SKU '+firstSku+' ／'}).locator('button').click();assert.equal(await page.locator('#selected-rows tr').count(),1);
 const remaining=await page.locator('#selected-rows').innerText();const event=page.waitForEvent('download');await page.locator('#download-selected-csv').click();const download=await event;const csv=fs.readFileSync(await download.path(),'utf8');
 assert(csv.startsWith('\uFEFF'));assert.equal(csv.split('\r\n').filter(Boolean).length,2);assert(!csv.includes('"'+firstSku+'"'));
 const remainingSku=remaining.match(/SKU (.*?) ／/)[1];assert(csv.includes('"'+remainingSku+'"'));
 await page.screenshot({path:'artifacts/vintage-normalization-20260929/production-selection.png',fullPage:true});
 assert.deepEqual(errors,[]);
 fs.writeFileSync('artifacts/vintage-normalization-20260929/production-acceptance.json',JSON.stringify({total:options.total,supplierMatches:result.rows.length,yearVariants:true,nvMatches:nv.rows.length,crossSearchSelection:true,reviewRemoval:true,selectedCsvRows:1,remainingSku,errors},null,2));
 console.log('Production API, canonical vintages, supplier search, cross-search selection, review and selected CSV passed');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
